html body .sort-picker-chip,
html body button.sort-picker-chip,
html body .deals-chip,
html body button.deals-chip,
html body .deals-chip.new-chip,
html body button.deals-chip.new-chip,
html body .toolbar-refresh,
html body button.toolbar-refresh,
html body .price-chip,
html body button.price-chip,
html body .sidebar .price-chip,
html body .item-rail-actions-cart,
html body button.item-rail-actions-cart,
html body .item-rail-actions-bargain,
html body button.item-rail-actions-bargain {
  height: var(--ctl-h) !important;
  min-height: var(--ctl-h) !important;
  border-radius: var(--ctl-r) !important;
  font-size: var(--ctl-fs-sm) !important;
  font-weight: var(--ctl-fw-sm) !important;
  background: var(--ctl-surface) !important;
  background-color: var(--ctl-surface) !important;
