html body .site-root.full-page-mode .modal-backdrop > .info-modal[aria-labelledby^="info-modal-h-sell-items"],
html body .full-page-mode .info-modal[aria-labelledby^="info-modal-h-database"],
html body .full-page-mode .info-modal[aria-labelledby^="info-modal-h-loadout-lab"],
html body .full-page-mode .info-modal[aria-labelledby^="info-modal-h-watchlist"],
html body .full-page-mode .info-modal[aria-labelledby^="info-modal-h-profile"],
html body .full-page-mode .info-modal[aria-labelledby^="info-modal-h-support"],
html body .full-page-mode .info-modal[aria-labelledby^="info-modal-h-incoming"],
html body .full-page-mode .info-modal[aria-labelledby^="info-modal-h-outgoing"],
