html body .listing-grid > .grid-card .grid-steam-price { font-size: 12px !important; color: var(--ink-4, #9a9a96) !important; }
html body .modal-stat-val.accent { font-size: 28px !important; font-weight: 700 !important; }

/* 2. Market card: one rarity treatment instead of three. The thumbnail gets a
      single vertical wash in the rarity colour and one 2px bar along its
      bottom edge; the diagonal hatch, the second top stripe and the extra
      glow layer go. Colours are the ones the cards already use per tier. */
html body .listing-grid > .grid-card { --card-rc: #3b82f6; }
html body .listing-grid > .grid-card:has(.rarity-Limited) { --card-rc: #eb4b82; }
html body .listing-grid > .grid-card:has(.rarity-Off-Market) { --card-rc: #e8b960; }
html body .listing-grid > .grid-card .grid-thumb {
  background: linear-gradient(180deg, var(--bg-1, #1e2127) 0%, color-mix(in oklab, var(--card-rc, #3b82f6) 16%, var(--bg-1, #1e2127)) 100%) !important;
}
html body .listing-grid > .grid-card .grid-thumb::after { display: none !important; }
html body .listing-grid > .grid-card .gc-rarity-top { display: none !important; }
html body .listing-grid > .grid-card .gc-rarity-bottom { height: 2px !important; background: var(--card-rc, #3b82f6) !important; opacity: 0.9; }
html body .listing-grid > .grid-card .grid-thumb img.item-img { filter: drop-shadow(0 10px 18px rgba(0, 0, 0, 0.45)); }

/* Card body on a 4px rhythm: name, category, then the price block. */
html body .listing-grid > .grid-card .grid-body { padding: 14px 16px 12px !important; gap: 2px; }
html body .listing-grid > .grid-card .grid-name { font-size: 15px !important; font-weight: 600 !important; line-height: 20px !important; color: var(--ink, #f4f4f2) !important; }
html body .listing-grid > .grid-card .grid-cat { font-size: 12px !important; color: var(--ink-3, #b8b8b4) !important; }
html body .listing-grid > .grid-card .grid-footer { margin-top: 10px !important; }
html body .listing-grid > .grid-card .gc-card-meta { color: var(--ink-4, #9a9a96) !important; }

/* Hover: lift 2px, rarity-tinted edge, image grows 4%. Nothing fades. */
html body .listing-grid > .grid-card {
  transition: transform 200ms cubic-bezier(.2,.8,.2,1), border-color 200ms cubic-bezier(.2,.8,.2,1), box-shadow 200ms cubic-bezier(.2,.8,.2,1) !important;
}
html body .listing-grid > .grid-card .grid-thumb img.item-img { transition: transform 320ms cubic-bezier(.2,.8,.2,1) !important; }
@media (hover: hover) {
  html body .listing-grid > .grid-card:hover {
    transform: translateY(-2px) !important;
    border-color: color-mix(in oklab, var(--card-rc, #3b82f6) 55%, var(--line-2, #3a3d45)) !important;
    box-shadow: 0 16px 36px -12px rgba(0, 0, 0, 0.7), 0 0 0 1px color-mix(in oklab, var(--card-rc, #3b82f6) 22%, transparent) !important;
    background-color: var(--bg-1, #1e2127) !important;
  }
  html body .listing-grid > .grid-card:hover .grid-thumb img.item-img { transform: scale(1.04) !important; }
}
html body .listing-grid > .grid-card:active { transform: translateY(0) !important; transition-duration: 120ms !important; }
@media (prefers-reduced-motion: reduce) {
  html body .listing-grid > .grid-card, html body .listing-grid > .grid-card:hover, html body .listing-grid > .grid-card .grid-thumb img.item-img { transform: none !important; transition: none !important; }
}

