html body .modal-listing-row > .modal-listing-price { flex: 0 0 auto !important; min-width: 84px !important; text-align: right !important; font-size: 15px !important; font-weight: 700 !important; font-variant-numeric: tabular-nums !important; color: var(--ink) !important; }
html body .modal-listing-row > .buy-btn { flex: 0 0 auto !important; min-width: 72px !important; }
@media (max-width: 640px) {
  html body .modal-listings .modal-listing-row, html body .modal.item-page .modal-listing-row { flex-wrap: wrap !important; }
  html body .modal-listing-row > .modal-seller-info { flex-basis: calc(100% - 52px) !important; }
  html body .modal-listing-row > .modal-listing-price { margin-left: auto !important; }
  /* The listing number is an internal id; on a phone it pushed the report
     flag onto a third line. */
  html body .modal-listing-row > .modal-seller-info + .modal-listing-condition { display: none !important; }
}

/* Recent sales: 44px rows with a 48px type column read as a list of cards;
   the references keep the sales log as a dense table. */
html body .recent-sales-list .recent-sales-row { display: grid !important; grid-template-columns: 76px minmax(0, 1fr) auto !important; gap: 12px !important; padding: 0 14px !important; height: 36px !important; min-height: 36px !important; font-size: 13px !important; }
/* The stall's sales rows carry the item name as a 4th cell, and My Stall's Sold
   rows lead with the item (no type cell); the 3-column item-page grid wrapped
