html body .stall-recent-sales .recent-sales-list .recent-sales-row { grid-template-columns: 76px minmax(0, 1fr) auto auto !important; }
html body .mystall-sold-summary + .recent-sales-list .recent-sales-row { grid-template-columns: minmax(0, 1fr) auto auto !important; }
html body .recent-sales-list .recent-sales-row:nth-child(even) { background: color-mix(in oklab, var(--bg-2) 45%, transparent) !important; }
html body .recent-sales-list .recent-sales-price { font-weight: 700 !important; font-variant-numeric: tabular-nums !important; color: var(--ink) !important; }
html body .recent-sales-list .recent-sales-time { color: var(--ink-3) !important; text-align: right !important; }

/* Card quick actions (+ add to cart, ♡ watch): a later `.grid-thumb > *`
   rule made them position: relative, so they sat in the image's flow, the +
   off-centre on the left and the ♡ over the item itself. Pinned top-right
   together, the way the reference markets place their card actions. */
html body div.grid-card .grid-cart-btn.grid-cart-btn, html body div.grid-card .grid-star.grid-star { position: absolute !important; z-index: 4 !important; left: auto !important; bottom: auto !important; margin: 0 !important; }
html body div.grid-card .grid-star.grid-star { top: 8px !important; right: 8px !important; }
html body div.grid-card .grid-cart-btn.grid-cart-btn { top: 8px !important; right: 44px !important; }
@media (max-width: 760px) {
  html body div.grid-card .grid-cart-btn.grid-cart-btn { right: 46px !important; }
}

/* Touch screens: those buttons only faded in on :hover, which a phone never
