html body .csfloat-empty-cart-rail-grid div.grid-card { display: flex !important; flex-direction: column !important; min-height: 0 !important; height: auto !important; font-size: 16px !important; line-height: 1.55 !important; color: var(--ink) !important; background: rgb(30, 33, 39) !important; border-top: 1px solid var(--line) !important; }
