html body .csfloat-empty-cart-rail-grid div.grid-card .gc-card-meta { display: flex !important; align-items: center !important; justify-content: space-between !important; gap: 8px !important; padding: 8px 0 0 !important; width: auto !important; font-size: 11px !important; line-height: 1.3 !important; color: var(--ink-3) !important; border-top: 1px solid var(--line) !important; }
