html body .modal.item-page .modal-demand-chip { display: inline-flex !important; align-items: center !important; justify-content: flex-start !important; gap: 4px !important; width: calc(50% - 4px) !important; height: 32px !important; min-height: 32px !important; margin: 0 8px 8px 0 !important; padding: 0 10px !important; box-sizing: border-box !important; vertical-align: top !important; font-size: 12px !important; letter-spacing: 0 !important; text-transform: none !important; white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important; border-radius: 8px !important; }
