html body a.modal-name-rarity[href$="rarity=Limited"] { color: rgb(235, 75, 130) !important; border-color: rgba(235, 75, 130, 0.45) !important; background: rgba(235, 75, 130, 0.1) !important; }
html body a.modal-name-rarity[href$="rarity=Off-Market"] { color: rgb(240, 188, 76) !important; border-color: rgba(240, 188, 76, 0.45) !important; background: rgba(240, 188, 76, 0.1) !important; }
