  html body .item-buy-bar .item-buy-bar-info { display: flex; flex-direction: column; gap: 2px; flex: 1 1 auto; min-width: 0; }
  html body .item-buy-bar .item-buy-bar-name { font: 500 12px/1.25 var(--ui); color: var(--ink-3); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  html body .item-buy-bar .item-buy-bar-price { font: 700 17px/1.2 var(--mono); color: var(--ink-1); font-feature-settings: "tnum"; }
  html body .item-buy-bar button.item-buy-bar-cart {
