@media (max-width: 720px) {
  html body:has(.cart-tray) .toast-stack, html body:has(.cart-tray) .sale-toasts, html body:has(.cart-tray) .sale-toast.sale-toast { bottom: calc(140px + env(safe-area-inset-bottom, 0px)) !important; }
  html body:has(.item-buy-bar) .toast-stack, html body:has(.item-buy-bar) .sale-toasts, html body:has(.item-buy-bar) .sale-toast.sale-toast { bottom: calc(132px + env(safe-area-inset-bottom, 0px)) !important; }
