  html body .db-table-scroll > table.db-table > tbody > tr.db-row .db-name { display: -webkit-box !important; -webkit-box-orient: vertical; -webkit-line-clamp: 2; min-height: 0 !important; white-space: normal !important; overflow: hidden !important; overflow-wrap: normal !important; line-height: 1.3 !important; text-align: left !important; }
  @container (min-width: 680px) and (max-width: 929.98px) {
    html body .db-table-scroll > table.db-table > thead > tr, html body .db-table-scroll > table.db-table > tbody > tr.db-row { grid-template-columns: minmax(0, 1fr) 104px 64px 56px 92px 40px !important; }
    html body .db-table-scroll > table.db-table > thead > tr > th:is(:nth-child(1), :nth-child(3), :nth-child(7)), html body .db-table-scroll > table.db-table > tbody > tr.db-row > td:is(:nth-child(1), :nth-child(3), :nth-child(7)) { display: none !important; }
