    html body .db-table-scroll > table.db-table > tbody > tr.db-row > td:nth-child(9) { grid-column: 5 !important; grid-row: 2 !important; justify-self: end !important; }
    html body .db-table-scroll > table.db-table > tbody > tr.db-row > td:is(:nth-child(5), :nth-child(6), :nth-child(7)) { grid-row: 2 !important; grid-column: auto !important; font-family: var(--mono); font-size: 11px !important; color: var(--ink-3) !important; text-align: left !important; white-space: nowrap !important; }
    html body .db-table-scroll > table.db-table > tbody > tr.db-row > td:nth-child(5)::before { content: 'Supply '; color: var(--ink-4); }
    html body .db-table-scroll > table.db-table > tbody > tr.db-row > td:nth-child(6)::before { content: '· Sold '; color: var(--ink-4); }
    html body .db-table-scroll > table.db-table > tbody > tr.db-row > td:nth-child(7)::before { content: '· '; color: var(--ink-4); }
