html body .modal-listing-row > .listing-offer-btn:focus-visible { outline: 2px solid var(--cta); outline-offset: 2px; }
html body .offer-drawer-target { color: var(--ink); font-weight: 600; }
@media (max-width: 768px) {
  html body .modal-listing-row > .listing-offer-btn { width: 40px; height: 40px; padding: 0; }
  html body .modal-listing-row > .listing-offer-btn .listing-offer-btn-label { display: none; }
}
@media (max-width: 640px) {
