  html:root body .csfloat-home-preview[aria-busy="true"] .csfloat-home-preview-row { min-height: 422px !important; }
}

/* Look refresh pass 8: the item picture stopped stretching to its frame
   once an older width rule was cut, leaving a 256px picture in a 520px
   frame on desktop; it fills 92% of the frame again at every width. */
html:root body .modal-preview > img.item-img.item-img { width: 92% !important; height: 92% !important; max-width: none !important; max-height: none !important; object-fit: contain !important; }
/* On phones the wallet card sat flush against the top bar while every
   other page starts 16px or more below it. */
@media (max-width: 720px) {
  html:root body .site-root.full-page-mode .modal-backdrop > .modal.wallet-modal.wallet-modal { margin-top: 16px !important; }
}
/* Sell page Steam notice: its two stacked buttons were 266px and 320px
   wide; they now share one width. */
html:root body .empty-inline > div:has(> a.btn[href*="steamcommunity.com/my/edit/settings"]) > .btn { width: 320px !important; max-width: 100% !important; justify-content: center !important; }
/* The bar's backdrop-filter made it the containing block for the menu's fixed backdrop (only 56px tall, so taps fell
   through to the page) and the backdrop root for the menus (their blur saw nothing, so they were see-through). */
html body nav.nav:has(#user-menu-panel), html body nav.nav:has(#notif-dropdown-panel) { -webkit-backdrop-filter: none !important; backdrop-filter: none !important; }
/* Phones: the account menu ran under the bottom tab bar (Settings and Logout hidden or unreachable). */
@media (max-width: 720px) {
  html body nav.nav:has(#user-menu-panel) { z-index: 1001 !important; }
  body #user-menu-panel { max-height: calc(100dvh - var(--nav-h, 56px) - 16px) !important; overscroll-behavior: contain; }
  /* Toasts sat on top of the bottom tab bar. The cart-tray and buy-bar offsets are more specific and still win. */
  html body .toast-stack, html body .sale-toasts, html body .sale-toast.sale-toast { bottom: calc(66px + env(safe-area-inset-bottom, 0px)) !important; }
}
